L34_1.m_Pos = "C"
L34_1.m_Talk_KOREA = "참으로 덧없군. 이 세계를 구하기 위해, 파트너와 나는 고군분투해왔는데 말이지……."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "儚いな。この世界を救おうと、私とパートナーはあれほど必死に動いていたというのに……"
L34_1.m_Talk_ENG = "How fleeting. My partner and I struggled so hard to save this world..."
L34_1.m_Talk_TWN = "真是無常啊。為了拯救這個世界，我和夥伴一直在努力奮鬥……"
L34_1.m_Talk_SCN = "真是无常啊。为了拯救这个世界，我和伙伴一直在努力奋斗……"
L34_1.m_Talk_DEU = "How fleeting. My partner and I struggled so hard to save this world..."
L34_1.m_Talk_FRA = "How fleeting. My partner and I struggled so hard to save this world..."
