L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "L"
L25_1 = "따라서 원래부터 허구였던 존재가 당신에 의해, 허무로 되돌아갔을 뿐이죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "つまり元から虚構に過ぎなかった存在が、あなたの手によって虚無に戻ったまでです。"
