L27_1.m_Pos = "L"
L28_1 = "자네 설마 대적자에 대해서 알고 있나? 그럼, 이야기가 빠르겠군."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "まさか君、敵対者について知っているのかね？　だったら話は早い。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "So you know about the Antagonist? That makes things simpler."
L27_1.m_Talk_ENG = L28_1
L28_1 = "你難道知道敵對者的事情嗎？那解釋起來就快了。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "你难道知道敌对者的事情吗？那解释起来就快了。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "So you know about the Antagonist? That makes things simpler."
L27_1.m_Talk_DEU = L28_1
L28_1 = "So you know about the Antagonist? That makes things simpler."
L27_1.m_Talk_FRA = L28_1
