L28_1.m_Pos = "L"
L29_1 = "전에 말한 이방인과 만난 뒤로, 나는 줄곧 우리 세계의 대적자를 찾아왔다네."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "前に話した異邦人と出会ってから、私はずっと私の世界の敵対者を探していた。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Ever since I met another outsider, I've been searching for the Antagonist of our world."
L28_1.m_Talk_ENG = L29_1
L29_1 = "自從遇到之前提到的外邦人後，我一直在尋找我們世界的敵對者。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "自从遇到之前提到的异乡人后，我一直在寻找我们世界的敌对者。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Ever since I met another outsider, I've been searching for the Antagonist of our world."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Ever since I met another outsider, I've been searching for the Antagonist of our world."
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
