L34_1 = "그녀는 로열 오페라 하우스의 프리마돈나였어."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "彼女はロイヤルオペラハウスのプリマドンナだった。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "She was the prima donna of the Royal Opera House."
L33_1.m_Talk_ENG = L34_1
L34_1 = "她曾是皇家歌劇院的首席女主角。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "她曾是皇家歌剧院的首席女主角。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "She was the prima donna of the Royal Opera House."
L33_1.m_Talk_DEU = L34_1
L34_1 = "She was the prima donna of the Royal Opera House."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP13_ACT4_INTERLUDE3@116#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 180
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 618
L34_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L35_1 = "겉모습은 가녀린 소녀처럼 보였지만, 사실은 누구보다 강한 의지를 지닌 여인이었네."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "見た目はか弱い少女だったが、本当は誰よりも強い意志を持っている女性だった。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "She looked like a delicate young woman, but had a stronger will than anyone I've known."
L34_1.m_Talk_ENG = L35_1
L35_1 = "外表看似纖弱的少女，實際上是比任何人都擁有強大意志的女人。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "外表看似纤弱的少女，实际上是比任何人都拥有强大意志的女人。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "She looked like a delicate young woman, but had a stronger will than anyone I've known."
L34_1.m_Talk_DEU = L35_1
L35_1 = "She looked like a delicate young woman, but had a stronger will than anyone I've known."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP13_ACT4_INTERLUDE3@117#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 181
L35_1.m_CutScenProcessKey = L36_1
