L35_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L36_1 = "설령 목숨을 위협받는 상황에서도, 배우로서 우아하게 살아가려고 했으니까."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "その命が危うい状況でさえも、俳優として優雅に生きる姿勢を崩そうとしなかったからね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Even when her life was on the line, she lived with grace, like a true performer."
L35_1.m_Talk_ENG = L36_1
L36_1 = "即使在生命受到威脅的情況下，她也想作為演員優雅地活下去。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "即使在生命受到威胁的情况下，她也想作为演员优雅地活下去。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Even when her life was on the line, she lived with grace, like a true performer."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Even when her life was on the line, she lived with grace, like a true performer."
L35_1.m_Talk_FRA = L36_1
