L44_1 = "하지만 나는 결국 마지막까지 그 사실을 전하지 못했어."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "しかし私は結局、最後までその事実を伝えることができなかった。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "But I never told her. Not even at the end."
L43_1.m_Talk_ENG = L44_1
L44_1 = "但最終我還是沒能告訴她這個事實。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "但最终我还是没能告诉她这个事实。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "But I never told her. Not even at the end."
L43_1.m_Talk_DEU = L44_1
L44_1 = "But I never told her. Not even at the end."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP13_ACT4_INTERLUDE3@122#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 190
L44_1.m_CutScenProcessKey = L45_1
L44_1.m_CutScenID = 618
L44_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE3"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L44_1.m_Pos = "L"
L45_1 = "망설이고 말았지. 이 세계의 모든 미지를 상대한다는 건, 그만큼 고독한 일이니까."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "迷ってしまったんだ。この世界の全ての未知を相手にするということは、それだけの孤独を背負うことに他ならないから。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I hesitated. Tackling all the unknown in this world is a lonely task, after all."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我猶豫了，因為獨自面對這個世界的所有未知，實在是一件孤獨的事情。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "我犹豫了，因为独自面对这个世界的所有未知，实在是一件孤独的事情。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "I hesitated. Tackling all the unknown in this world is a lonely task, after all."
L44_1.m_Talk_DEU = L45_1
L45_1 = "I hesitated. Tackling all the unknown in this world is a lonely task, after all."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
L46_1 = "EP13_ACT4_INTERLUDE3@123#Talk"
L45_1.m_CutScenKey_Talk = L46_1
L46_1 = 191
L45_1.m_CutScenProcessKey = L46_1
L45_1.m_CutScenID = 618
L45_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE3"
