L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L45_1.m_Pos = "L"
L46_1 = "그건 누구보다도 내가 가장 잘 알고 있으니까."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "それは誰よりも私が一番よく知っている。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "And I know that better than anyone."
L45_1.m_Talk_ENG = L46_1
L46_1 = "因為這件事我比任何人都清楚。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "因为这件事我比任何人都清楚。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "And I know that better than anyone."
