L3_1 = "나는 만들어진 허상일 뿐. 그리고 이곳에 있는 스완은 내가 아는 그녀와는 다른 존재지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "私は作られた虚像に過ぎない。そしてここにいるスワンは、私の知っている彼女とは違う存在だ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I'm just an illusion. And this Swan is not the one I know."
L2_1.m_Talk_ENG = L3_1
L3_1 = "我只是一個被創造的幻影。而這裡的史旺與我所認識的她是不同的存在。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "我只是一个被创造的幻影。而这里的斯旺与我所认识的她是不同的存在。"
L2_1.m_Talk_SCN = L3_1
L3_1 = "I'm just an illusion. And this Swan is not the one I know."
L2_1.m_Talk_DEU = L3_1
L3_1 = "I'm just an illusion. And this Swan is not the one I know."
L2_1.m_Talk_FRA = L3_1
