L7_1.m_Pos = "L"
L8_1 = "알다시피, 대적자는 마왕으로부터 세계를 수호하는 존재야."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "知っての通り、敵対者は魔王から世界を守護する存在だ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "As you know, the Antagonist is someone meant to protect a world from the Demon Lord."
L7_1.m_Talk_ENG = L8_1
L8_1 = "如你所知，敵對者是從魔王手中守護世界的存在。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "如你所知，敌对者是从魔王手中守护世界的存在。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "As you know, the Antagonist is someone meant to protect a world from the Demon Lord."
L7_1.m_Talk_DEU = L8_1
L8_1 = "As you know, the Antagonist is someone meant to protect a world from the Demon Lord."
