L9_1 = "이건 어디까지나 내 직감이지만……."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "あくまでも私の直感に過ぎないが……"
L8_1.m_Talk_JPN = L9_1
L9_1 = "It's just a gut feeling, but..."
L8_1.m_Talk_ENG = L9_1
L9_1 = "這只是我的直覺……"
