L10_1 = "EP13_ACT4_INTERLUDE3@134#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 205
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 618
L9_1.m_CutScenStrID = "EP13_ACT4_INTERLUDE3"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Face = "UNIT_SERIOUS"
L9_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L9_1.m_Pos = "L"
L10_1 = "만약 그렇다면, 그녀는 어떤 <color=#ffd34c>대의</color>를 위해, 스스로 악을 자처하고 있을 가능성이 있어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "もしそうだとしたら、彼女はとある<color=#ffd34c>大義</color>のために、自ら悪を自称している可能性がある。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "Maybe, just maybe, she took on the role of a villain for a <color=#ffd34c>greater cause</color>."
L9_1.m_Talk_ENG = L10_1
L10_1 = "如果是這樣的話，她可能是為了某種<color=#ffd34c>大義</color>，自願扮演惡人的角色。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "如果是这样的话，她可能是为了某种<color=#ffd34c>大义</color>，自愿扮演恶人的角色。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Maybe, just maybe, she took on the role of a villain for a <color=#ffd34c>greater cause</color>."
L9_1.m_Talk_DEU = L10_1
L10_1 = "Maybe, just maybe, she took on the role of a villain for a <color=#ffd34c>greater cause</color>."
