L12_1 = "UNIT_DESPAIR"
L11_1.m_Face = L12_1
L11_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L11_1.m_Pos = "C"
L12_1 = "그녀는 대적자로서 자신만의 방식으로, 자신만의 싸움을 하고 있을지도 몰라."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "彼女は敵対者として、自分だけの方法で、自分だけの戦いをしているのかもしれない。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Maybe this is her way of fighting as the Antagonist."
L11_1.m_Talk_ENG = L12_1
L12_1 = "她可能正在以她自己的方式，以她自己的戰鬥方式，作為敵對者進行戰鬥。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "她可能正在以她自己的方式，以她自己的战斗方式，作为敌对者进行战斗。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Maybe this is her way of fighting as the Antagonist."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Maybe this is her way of fighting as the Antagonist."
L11_1.m_Talk_FRA = L12_1
L12_1 = {}
