L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L12_1.m_Pos = "C"
L13_1 = "어쩌면 그녀는 이해할 수도, 가늠할 수조차 없는 고독한 인생을 살아왔던 걸지도 모르지."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "もしかすると彼女は、理解も、想像もできないほど孤独な人生を生きてきたのかもしれないのだ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Maybe she's lived a life so lonely, no one could even comprehend it."
L12_1.m_Talk_ENG = L13_1
L13_1 = "或許她過著我們無法理解也無法想像的孤獨的生活。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "或许她过着我们无法理解也无法想象的孤独的生活。"
