L31_1.m_Talk_ENG = L32_1
L32_1 = "而且無論是什麼，都不應該隨意犧牲他人的生命。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "而且无论是什么，都不应该随意牺牲他人的生命。"
