L43_1 = "스완은 그 아이의 본질이 세피라. 즉, 세계를 만드는 법칙의 일부라고 했어."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "スワンはあの子の本質がセフィラ、つまり、世界を作る法則の一部だと言った。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Swan said it herself that the girl's essence is Sephira. A part of the law of creating a world."
L42_1.m_Talk_ENG = L43_1
L43_1 = "史旺說那個孩子的本質是生命樹，也就是構成世界法則的一部分。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "斯旺说那个孩子的本质是塞菲拉，也就是构成世界法则的一部分。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Swan said it herself that the girl's essence is Sephira. A part of the law of creating a world."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Swan said it herself that the girl's essence is Sephira. A part of the law of creating a world."
L42_1.m_Talk_FRA = L43_1
