L43_1.m_Pos = "L"
L44_1 = "다시 말해, 그 아이가 진심으로 바라는 건 현실이 되어버린다는 뜻이지."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "言い換えれば、あの子が本心から願うことは現実になるということさ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "In other words, her wishes become reality."
L43_1.m_Talk_ENG = L44_1
L44_1 = "換句話說，那孩子真心渴望的東西會變成現實。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "换句话说，那孩子真心渴望的东西会变成现实。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "In other words, her wishes become reality."
L43_1.m_Talk_DEU = L44_1
L44_1 = "In other words, her wishes become reality."
