L9_1.m_fTalkTime = 0.03
L10_1 = "ということは、あの子がどこかで私を観測し、私が存在し続けることを願っているということではないかね？"
L9_1.m_Talk_JPN = L10_1
L10_1 = "And that means someone out there still sees me, still wants me to be."
L9_1.m_Talk_ENG = L10_1
L10_1 = "那就是說，那孩子在某處觀察我，並希望我存在的意思吧？"
L9_1.m_Talk_TWN = L10_1
L10_1 = "那就是说，那孩子在某处观察我，并希望我存在的意思吧？"
L9_1.m_Talk_SCN = L10_1
L10_1 = "And that means someone out there still sees me, still wants me to be."
L9_1.m_Talk_DEU = L10_1
L10_1 = "And that means someone out there still sees me, still wants me to be."
L9_1.m_Talk_FRA = L10_1
